 for p in select * from jsonb_array_elements('[{"id":"lifefit-fbw-male-balanced-intermediate","name":"אימון FBW לגברים משקולות ומכונות מתאמן בינוני","description":"כיסוי חזה, גב, רגליים, ישבן, כתפיים, יד קדמית, יד אחורית ובטן. 3 אימונים בשבוע; רמת בינוני. כאשר כל הסטים וכל החזרות הושלמו בטכניקה יציבה ובעצימות היעד, מעלים את המשקל בצעד הקטן הזמין. ב־TRX מקשים מעט את זווית הגוף. אם הטכניקה נפגעת, מפחיתים עומס. אין חובה להגיע לכשל. מנוחה של לפחות יום בין אימוני גוף מלא. ב־PPL מתחלפים Push/Pull/Legs ברצף גם בין שבועות; ב־A-B מתחלפים A/B.  ","programType":"FBW","difficulty":"בינוני","trainingFrequency":3,"equipment":["משקולות","מכונות","כבל פולי"],"sourceWorkbook":"LIFE FIT — תוכניות לפי אפיון לקוח","status":"active","official":true,"days":[{"id":"lifefit-fbw-male-balanced-intermediate-day-0","name":"FBW A","order":0,"exercises":[{"id":"lifefit-fbw-male-balanced-intermediate-day-0-warmup","exerciseId":"exercise-155pu7s","order":0,"notes":"חימום דינמי לפי אימון, ולאחריו סטי הכנה לתרגיל העמוס הראשון. החימום אינו סט עבודה."},{"id":"lifefit-fbw-male-balanced-intermediate-day-0-ex-0","exerciseId":"exercise-1w08fkm","order":1,"sets":"3","reps":"10","rest":"120 שניות","effort":"8","notes":"להשאיר כ־2 חזרות במיכל.","setPrescriptions":[{"id":"lifefit-fbw-male-balanced-intermediate-day-0-ex-0-set-0","order":0,"repetitions":"10"},{"id":"lifefit-fbw-male-balanced-intermediate-day-0-ex-0-set-1","order":1,"repetitions":"10"},{"id":"lifefit-fbw-male-balanced-intermediate-day-0-ex-0-set-2","order":2,"repetitions":"10"}]},{"id":"lifefit-fbw-male-balanced-intermediate-day-0-ex-1","exerciseId":"resistance-dumbbell-stiff-legged-deadlift-copy","order":2,"sets":"3","reps":"10","rest":"120 שניות","effort":"8","notes":"להשאיר כ־2 חזרות במיכל.","setPrescriptions":[{"id":"lifefit-fbw-male-balanced-intermediate-day-0-ex-1-set-0","order":0,"repetitions":"10"},{"id":"lifefit-fbw-male-balanced-intermediate-day-0-ex-1-set-1","order":1,"repetitions":"10"},{"id":"lifefit-fbw-male-balanced-intermediate-d